"use client";

/**
 * Compare split: the old screen and the new one in the same frame, split by a
 * handle that sweeps across. It stops halfway so both sides read, then hands
 * the frame to the new screen and holds there.
 *
 * Written by Better Design. Painted from the theme prop; with no pictures it
 * draws a crowded old page and a calm new one from the same tokens.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

/** Timing, in frames: the handle arrives, rests at the middle, then hands over. */
const ARRIVE_AT = 8;
const ARRIVE_FRAMES = 34;
const HANDOVER_AT = 78;
const HANDOVER_FRAMES = 36;

/** Where the split stands, as a fraction of the screen width from the left. */
const SPLIT_START = 0.94;
const SPLIT_REST = 0.5;
const SPLIT_END = 0.08;


export interface CompareSplitProps {
  /** The old screen: a path in `public/` or a URL. Drawn as a crowded placeholder page when absent. */
  before?: string;
  /** The new screen. Drawn as a calm placeholder page when absent. */
  after?: string;
  beforeLabel?: string;
  afterLabel?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const bar = (width: string, height: number, background: string) => (
  <div style={{ width, height, borderRadius: height / 2, background, flexShrink: 0 }} />
);

/** The old page: too many columns, too many weights, nothing leads. */
function CrowdedPage({ theme }: { theme: VideoTheme }) {
  const ink = withAlpha(theme.foreground, 0.22);
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.muted, display: "flex", flexDirection: "column", gap: 22, padding: "3% 4%" }}>
      <div style={{ display: "flex", gap: 18, alignItems: "center" }}>
        {[14, 9, 12, 8, 11, 10, 9].map((w, i) => (
          <div key={i}>{bar(`${w * 10}px`, 14, ink)}</div>
        ))}
      </div>
      <div style={{ flex: 1, display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 18 }}>
        {Array.from({ length: 12 }, (_, i) => (
          <div key={i} style={{ background: theme.card, border: `1px solid ${theme.border}`, borderRadius: 6, padding: 18, display: "flex", flexDirection: "column", gap: 12 }}>
            {bar(`${50 + ((i * 17) % 40)}%`, 12, withAlpha(theme.foreground, 0.45))}
            {bar("90%", 9, ink)}
            {bar(`${60 + ((i * 11) % 30)}%`, 9, ink)}
            {i % 3 === 0 ? bar("40%", 22, withAlpha(theme.destructive, 0.35)) : null}
          </div>
        ))}
      </div>
    </div>
  );
}

/** The new page: one headline, one action, one picture of the product. */
function CalmPage({ theme }: { theme: VideoTheme }) {
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.background, display: "flex", alignItems: "center", gap: "6%", padding: "0 8%" }}>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 28 }}>
        {bar("34%", 16, withAlpha(theme.primary, 0.55))}
        {bar("94%", 58, withAlpha(theme.foreground, 0.86))}
        {bar("68%", 58, withAlpha(theme.foreground, 0.86))}
        {bar("78%", 16, withAlpha(theme.foreground, 0.18))}
        <div style={{ width: 240, height: 68, borderRadius: 34, background: theme.primary, marginTop: 16 }} />
      </div>
      <div style={{ flex: 1, height: "64%", borderRadius: theme.radius * 2, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", alignItems: "flex-end", gap: 18, padding: 40 }}>
        {[0.34, 0.5, 0.44, 0.7, 0.92].map((h, i) => (
          <div key={i} style={{ flex: 1, height: `${h * 100}%`, borderRadius: 12, background: i === 4 ? theme.primary : withAlpha(theme.primary, 0.18) }} />
        ))}
      </div>
    </div>
  );
}

/** Two screens in one frame, split by a handle that hands the frame from the old to the new. */
export function CompareSplit({ before, after, beforeLabel = "Before", afterLabel = "After", theme: themeOverride, font }: CompareSplitProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const arrive = easings.out(progress(frame, ARRIVE_AT, ARRIVE_FRAMES));
  const handover = easings.inOut(progress(frame, HANDOVER_AT, HANDOVER_FRAMES));
  const split = SPLIT_START + (SPLIT_REST - SPLIT_START) * arrive + (SPLIT_END - SPLIT_REST) * handover;
  const enter = easings.out(progress(frame, 0, 14));
  // A label fades as its side of the frame closes, so it never sits on the wrong screen.
  const beforeShown = progress(split, 0.12, 0.2);
  const afterShown = progress(1 - split, 0.12, 0.2);

  const picture = (src: string) => <Img src={srcOf(src)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />;
  const label = (text: string, side: "left" | "right", shown: number) => (
    <div
      style={{
        position: "absolute",
        top: 32,
        [side]: 32,
        padding: "12px 22px",
        borderRadius: 999,
        background: theme.card,
        boxShadow: `0 6px 18px -8px ${withAlpha(theme.foreground, 0.35)}`,
        zIndex: 2,
        border: `1px solid ${theme.border}`,
        color: theme.foreground,
        fontFamily: family,
        fontWeight: 600,
        fontSize: 26,
        opacity: shown,
      }}
    >
      {text}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center" }}>
      <div
        style={{
          position: "relative",
          width: "86%",
          height: "82%",
          borderRadius: theme.radius * 2,
          overflow: "hidden",
          border: `1px solid ${theme.border}`,
          boxShadow: `0 40px 90px -40px ${withAlpha(theme.foreground, 0.35)}`,
          opacity: enter,
          transform: `translateY(${(1 - enter) * 24}px)`,
        }}
      >
        {before ? picture(before) : <CrowdedPage theme={theme} />}
        <div style={{ position: "absolute", inset: 0, clipPath: `inset(0 0 0 ${split * 100}%)` }}>
          {after ? picture(after) : <CalmPage theme={theme} />}
        </div>
        <div style={{ position: "absolute", top: 0, bottom: 0, left: `${split * 100}%`, width: 4, marginLeft: -2, background: theme.primaryForeground, boxShadow: `0 0 0 1px ${withAlpha(theme.foreground, 0.2)}` }} />
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: `${split * 100}%`,
            width: 72,
            height: 72,
            marginLeft: -36,
            marginTop: -36,
            borderRadius: 36,
            background: theme.primary,
            boxShadow: `0 12px 30px -8px ${withAlpha(theme.foreground, 0.45)}`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 8,
          }}
        >
          {[1, -1].map((dir) => (
            <div key={dir} style={{ width: 0, height: 0, borderTop: "9px solid transparent", borderBottom: "9px solid transparent", [dir === 1 ? "borderRight" : "borderLeft"]: `12px solid ${theme.primaryForeground}` }} />
          ))}
        </div>
        {label(beforeLabel, "left", beforeShown)}
        {label(afterLabel, "right", afterShown)}
      </div>
    </AbsoluteFill>
  );
}
